/* Screen reader only utility class */
.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    border: 0;
}

/* Universal accessible focus states */
:focus-visible {
    outline: 3px solid var(--focus-ring);
    outline-offset: 3px;
}

/* Skip link for keyboard users */
.skip-link {
    position: absolute;
    top: -100px;
    left: 1rem;
    background: var(--primary-color);
    color: white;
    padding: 0.75rem 1rem;
    font-weight: 600;
    z-index: 1000;
    text-decoration: none;
    border-radius: 4px;
    transition: top 0.2s;
}

.skip-link:focus {
    top: 1rem;
}

/* Typography */
h1, h2, h3, h4 {
    color: var(--primary-color);
    font-weight: 700;
    line-height: 1.2;
}

a {
    color: var(--primary-color);
    text-decoration: none;
    transition: color 0.2s ease;
}

a:hover {
    text-decoration: underline;
}

/* Layout Utilities */
.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 1.5rem;
}

.section-padding {
    padding: 5rem 0;
}

.bg-alt {
    background-color: var(--bg-alt);
}

.section-title {
    font-size: 2rem;
    margin-bottom: 2.5rem;
    text-align: center;
}

/* Buttons */
.btn {
    display: inline-block;
    padding: 0.75rem 1.5rem;
    font-size: 1rem;
    font-weight: 600;
    text-align: center;
    cursor: pointer;
    border: none;
    border-radius: 4px;
    transition: all 0.2s ease;
    text-decoration: none;
    font-family: inherit;
}

.btn-primary {
    background-color: var(--primary-color);
    color: white;
}

.btn-primary:hover {
    background-color: #000;
    text-decoration: none;
}

.btn-secondary {
    background-color: white;
    color: var(--primary-color);
    border: 1px solid var(--primary-color);
}

.btn-secondary:hover {
    background-color: var(--secondary-color);
    text-decoration: none;
}

/* Header & Navigation */
.site-header {
    border-bottom: 1px solid var(--border-color);
    position: sticky;
    top: 0;
    background-color: white;
    z-index: 100;
