.hero h1 {
    color: white;
    font-size: clamp(2.5rem, 5vw, 4rem);
    margin-bottom: 1.25rem;
}

.hero p {
    font-size: 1.25rem;
    margin-bottom: 2.5rem;
    color: #e5e7eb;
