    // --- Elements ---
    const cartCountEl = document.querySelector('.cart-count');
    const addToCartBtns = document.querySelectorAll('.add-to-cart');
    const announcer = document.getElementById('announcer');
    const mobileMenuBtn = document.querySelector('.mobile-menu-btn');
    const navList = document.getElementById('nav-list');
    const cartBtn = document.querySelector('.cart-btn');

    // --- State ---
    let cartCount = 0;

    // --- Functions ---

    // Handles adding items to the cart
    const handleAddToCart = (e) => {
        const btn = e.target;
        const productName = btn.getAttribute('data-product');
        const originalText = btn.textContent;

        // Update state
        cartCount++;

        // Update visual counter
        cartCountEl.textContent = cartCount;

        // Update ARIA label on the cart button for screen readers navigating the header
        cartBtn.setAttribute('aria-label', `Shopping Cart, ${cartCount} items`);

        // Announce change immediately to screen readers
        announcer.textContent = `${productName} added to your cart. You now have ${cartCount} item${cartCount === 1 ? '' : 's'}.`;

        // Visual feedback on the button
        btn.textContent = 'Added!';
        btn.style.backgroundColor = '#f3f4f6';
        btn.setAttribute('disabled', 'true');

        // Reset button state after a short delay
        setTimeout(() => {
            btn.textContent = originalText;
            btn.style.backgroundColor = '';
            btn.removeAttribute('disabled');
        }, 2000);
    };

    // Handles mobile navigation toggle
    const toggleMobileMenu = () => {
        const isExpanded = mobileMenuBtn.getAttribute('aria-expanded') === 'true';

        // Toggle ARIA state
        mobileMenuBtn.setAttribute('aria-expanded', !isExpanded);

        // Toggle menu visibility
        navList.classList.toggle('active');

        // Update button text for screen readers and visual users
        mobileMenuBtn.textContent = !isExpanded ? 'Close Menu' : 'Menu';
    };

    // --- Event Listeners ---

    addToCartBtns.forEach(btn => {
        btn.addEventListener('click', handleAddToCart);
    });

    if (mobileMenuBtn && navList) {
        mobileMenuBtn.addEventListener('click', toggleMobileMenu);
    }
