+    display: flex;
+    flex-direction: column;
+    flex-grow: 1;
+}
+
+.product-title {
+    font-size: 1.125rem;
+    margin-bottom: 0.5rem;
+    font-weight: 600;
+}
+
+.product-price {
+    color: var(--text-muted);
+    font-weight: 500;
+    margin-bottom: 1rem;
+    flex-grow: 1;
+}
+
+.sale-price {
+    color: var(--accent-color);
+    font-weight: 700;
+    margin-left: 0.5rem;
+}
+
+.badge {
+    position: absolute;
+    top: 1rem;
+    left: 1rem;
+    background: var(--accent-color);
+    color: white;
+    padding: 0.25rem 0.75rem;
+    font-size: 0.875rem;
+    font-weight: 700;
+    border-radius: 4px;
+    z-index: 10;
+    letter-spacing: 0.5px;
+}
+
+.add-to-cart {
+    width: 100%;
+}
+
+/* Editorial Section */
+.editorial-grid {
+    display: grid;
+    grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
+    gap: 3rem;
+}
+
+.editorial-card {
+    background: white;
+    border-radius: 8px;
+    overflow: hidden;
+    box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05);
+}
+
+.editorial-card img {
+    width: 100%;
+    height: 350px;
+    object-fit: cover;
+}
+
+.editorial-content {
+    padding: 2.5rem 2rem;
+}
+
+.editorial-content h3 {
+    font-size: 1.75rem;
+    margin-bottom: 1rem;
+}
+
+.editorial-content p {
+    margin-bottom: 2rem;
+    color: var(--text-muted);
+    font-size: 1.125rem;
+}
+
+.btn-link {
+    font-weight: 700;
+    text-transform: uppercase;
+    letter-spacing: 1px;
+    font-size: 0.875rem;
+    display: inline-flex;
+    align-items: center;
+    gap: 0.5rem;
+}
+
+.btn-link::after {
+    content: "→";
+    transition: transform 0.2s ease;
+}
+
+.btn-link:hover {
+    text-decoration: none;
+}
+
+.btn-link:hover::after {
+    transform: translateX(4px);
+}
+
+/* Footer */
+.site-footer {
+    background: var(--primary-color);
+    color: white;
+    padding: 5rem 0 2rem;
+}
+
+.site-footer h2, 
+.site-footer h3 {
+    color: white;
+    margin-bottom: 1.5rem;
+}
+
+.footer-grid {
+    display: grid;
+    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
+    gap: 3rem;
+    margin-bottom: 4rem;
+}
+
+.site-footer ul {
+    list-style: none;
+}
+
+.site-footer ul li {
+    margin-bottom: 0.75rem;
+}
+
+.site-footer a {
+    color: #9ca3af;
+    text-decoration: none;
+}
+
+.site-footer a:hover {
+    color: white;
+    text-decoration: underline;
+}
+
+.footer-bottom {
+    border-top: 1px solid #374151;
+    padding-top: 2rem;
+    text-align: center;
+    color: #9ca3af;
+    font-size: 0.875rem;
+}
+
+/* Responsive Styles */
+@media (max-width: 768px) {
+    .nav-list {
+        display: none;
+        position: absolute;
+        top: 100%;
+        left: 0;
+        right: 0;
+        background: white;
+        padding: 1.5rem;
+        flex-direction: column;
+        gap: 1.5rem;
+        border-bottom: 1px solid var(--border-color);
+        box-shadow: 0 4px 6px -1px rgba(0,0,0,0.05);
+    }
+
+    .nav-list.active {
+        display: flex;
+    }
+
+    .mobile-menu-btn {
+        display: block;
+    }
+
+    .hero {
+        padding: 5rem 1.5rem;
+    }
+    
+    .section-padding {
+        padding: 3rem 0;
+    }
+}
')
